"""Build the human-readable, self-contained diagnostic HTML from frozen measurements."""
import collections
import html
import importlib.util
import json
import math
from pathlib import Path
import statistics
import time
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]

def load(name,path):
    s=importlib.util.spec_from_file_location(name,path);m=importlib.util.module_from_spec(s);s.loader.exec_module(m);return m

def table(headers,rows,caption=None):
    text='<div class="table-wrap"><table>'
    if caption:text+='<caption>'+html.escape(caption)+'</caption>'
    text+='<thead><tr>'+''.join('<th scope="col">'+html.escape(str(v))+'</th>' for v in headers)+'</tr></thead><tbody>'
    for row in rows:text+='<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>'
    return text+'</tbody></table></div>'

def read_json(path):return json.loads(Path(path).read_text())

def run():
    start=time.perf_counter();r=read_json(HERE/'report.json');context=read_json(HERE/'context-and-phase-probes.json')
    charts=load('chart_helpers',ROOT/'diagnostic_04c/plots.py');io=load('frozen_io',ROOT/'results/experiment-04d-majorsaw-reconstruction/reconstruct.py')
    D=ROOT/'results/experiment-04d-majorsaw-reconstruction';F=ROOT/'results/experiment-04f-independent'
    rate=r['sample_rate'];channels=r['channels'];wave={label:io.read_export(path)[2] for label,path in [
        ('Original',D/'original_reference.wav'),('4D baseline',D/'reconstructed.wav'),('4F-B',F/'b-related-shapes/reconstructed.wav'),('B residual',F/'b-related-shapes/residual.wav')]}
    records={v['cycle']:v for v in r['cycle_records']};gaps=r['interruptions'];frames=r['frames']
    def gap_for(row):
        center=(row['start_seconds']+row['end_seconds'])/2
        return next((v['interruption'] for v in gaps if v['start_seconds']<=center<v['end_seconds']),None)
    remaining=[v for v in r['cycle_records'] if v['original_status']=='ambiguous' and not v['accepted_by_b']]
    neighbor=max((v for v in remaining if set(v['b_rejection_reasons'])=={'unreliable immediate neighbor'}),key=lambda v:v['original_energy'])
    shape_only=max((v for v in remaining if set(v['b_rejection_reasons'])=={'target shape similarity too low'}),key=lambda v:v['original_energy'])
    spikes=r['residual_spikes']['4F-B']['events'];sharp=next(v for v in spikes if v['narrow_relative_to_period'] and v['modeled_fraction']==1 and .055<v['peak_seconds']<.1)
    transition=max((v for v in r['cycle_records'] if v['original_status']=='unreliable' and 2.49<v['start_seconds']<2.53),key=lambda v:v['original_energy'])
    restored=max((v for v in r['cycle_records'] if v['recovered_by_b'] and 1.28<v['start_seconds']<1.38),key=lambda v:v['original_energy'])
    family2=r['families'][1]
    cases=[('W1','Initial partial-cycle omission',0.,.014,None),
           ('W2','Short residual burst at an audio-energy onset',max(0,r['audio_energy_onsets'][5]['onset_seconds']-.003),.025,None),
           ('W3','Neighbor-only rejection',max(0,neighbor['start_seconds']-.005),.020,neighbor),
           ('W4','Strict target-shape gate',max(0,shape_only['start_seconds']-.005),.020,shape_only),
           ('W5','Periodic narrow detail spikes; no missing cycles',sharp['peak_seconds']-.006,.012,records[sharp['cycle']]),
           ('W6','Uncertain detection near a pitch-region transition',transition['start_seconds']-.006,.022,transition),
           ('W7','Release-derived exemplar (family 2)',family2['prototype_time_seconds']-.008,.020,records[family2['prototype_cycle']]),
           ('W8','A cycle recovered by frozen 4F-B',restored['start_seconds']-.005,.020,restored)]
    figures=[];case_rows=[]
    for label,title,begin,span,row in cases:
        a=max(0,math.floor(begin*rate));z=min(frames,math.ceil((begin+span)*rate));series=[]
        show=['Original','4F-B','B residual'] if label!='W8' else ['Original','4D baseline','4F-B','B residual']
        for name in show:series.append((name,[((frame-a)/rate,wave[name][frame*channels]) for frame in range(a,z)]))
        top=max(abs(v) for name,pts in series for x,v in pts)*1.1
        body=f'<text x="80" y="35" font-size="24" font-weight="700">{label} — {html.escape(title)}</text>'
        if row:
            left=max(a,row['start_frame']);right=min(z,row['end_frame'])
            if right>left:body+=f'<rect x="{90+(left-a)/(z-a)*920}" y="120" width="{(right-left)/(z-a)*920}" height="230" fill="#e9edf2"/>'
        body+=charts.chart(90,120,920,230,series,(z-a)/rate,-top,top,'Seconds from displayed window start','Decoded amplitude',f'Original time {a/rate:.6f}–{z/rate:.6f} s')
        body+='<text x="90" y="475" font-size="14">Reference channel shown; no visual amplitude normalization. A shaded cycle is a location annotation, not a changed assignment.</text>'
        path=HERE/f'{label.lower()}-waveform.svg';charts.save_svg(path,title,'Measured original, frozen reconstruction and residual at a labelled diagnostic location.',body,510)
        svg=path.read_text().replace('id="title"',f'id="{label}-title"').replace('id="desc"',f'id="{label}-desc"').replace('aria-labelledby="title desc"',f'aria-labelledby="{label}-title {label}-desc"')
        caption=f'Original time {a/rate:.6f}–{z/rate:.6f} s.'
        if row:
            gap=gap_for(row);caption+=f" Cycle {row['cycle']}; frozen status {html.escape(row['original_status'])}; {html.escape(row['cause'])}."
            if gap:caption+=f' Interruption <a href="#gap-{gap}">{gap}</a>.'
        figures.append(f'<figure id="{label}">{svg}<figcaption>{caption}</figcaption></figure>')
        case_rows.append([f'<a href="#{label}">{label}</a>',html.escape(title),f'{a/rate:.6f}–{z/rate:.6f}',str(row['cycle']) if row else 'boundary/onset'])
    # Family geometry: same observed 64-point signatures, no changed alignment.
    series=[(f"Family {v['family']} ({v['historical_unambiguous_cycles']} cycles)",[(i/64,x) for i,x in enumerate(v['prototype_shape'][:64])]) for v in r['families'] if v['status']=='recurring']
    low=min(x for label,pts in series for t,x in pts)-.2;high=max(x for label,pts in series for t,x in pts)+.2
    body='<text x="80" y="35" font-size="25" font-weight="700">Frozen recurring-family exemplars</text>'
    body+=charts.chart(90,120,920,260,series,1,low,high,'Normalized cycle position','Amplitude / saved stereo RMS','Signed geometry at the original saved phase anchor')
    charts.save_svg(HERE/'family-shapes.svg','Four frozen recurring family exemplars','Observed recurring exemplar geometry without family merging or rephasing.',body,550)
    family_svg=(HERE/'family-shapes.svg').read_text().replace('id="title"','id="family-title"').replace('id="desc"','id="family-desc"').replace('aria-labelledby="title desc"','aria-labelledby="family-title family-desc"')
    summary=[]
    bparts=r['residual_energy_parts']['4F-B'];btotal=sum(bparts.values())
    for status in ['ambiguous','unreliable','provisional']:
        selected=[v for v in r['cycle_records'] if not v['accepted_by_b'] and v['original_status']==status]
        energy=sum(v['original_energy'] for v in selected)
        summary.append([html.escape(status),str(len(selected)),f'{energy/btotal*100:.2f}%',html.escape({'ambiguous':'Frozen B evidence gates reject candidate cycle','unreliable':'Crossing/periodicity candidate not trusted','provisional':'Unconfirmed family not rendered'}[status])])
    summary.append(['Accepted model error',str(sum(v['accepted_by_b'] for v in r['cycle_records'])),f"{100*bparts['accepted_model_error']/btotal:.2f}%",'Detail/phase/amplitude mismatch within rendered support'])
    remaining_energy=r['ambiguous_comparison']['remaining_194']['source_energy'];nearby=r['neighbor_only_cases'];bad=[v for case in nearby for v in case['invalid_immediate_neighbors']]
    spike_rows=[]
    accepted_counts={'4D':1416,'A-cubic64':1416,'A-linear256':1416,'A-harmonic':1416,'4F-B':1938}
    for name,sp in r['residual_spikes'].items():
        events=[v for v in sp['events'] if v['narrow_relative_to_period'] and v['modeled_fraction']==1]
        spike_rows.append([html.escape(name),str(len(events)),f'{len(events)/accepted_counts[name]*100:.1f} per 100 rendered cycles',f"{sp['phase_distribution']['median']:.4f}",f"{sp['near_sharp_edge_fraction']*100:.1f}%",f"{sp['bridge_zone_fraction']*100:.1f}%"])
    fam_rows=[]
    for f in r['families']:
        if f['status']!='recurring':continue
        ph=context['refined_family_contexts'][str(f['family'])]
        freq=f['pitch_distribution_hz'];fam_rows.append([str(f['family']),str(f['exemplar_count']),str(f['historical_unambiguous_cycles']),str(f['b_rendered_cycles']),f"{f['prototype_time_seconds']:.6f}",html.escape(ph['prototype_context']),f"{freq['min']:.1f} / {freq['median']:.1f} / {freq['max']:.1f}",html.escape(str(f['audio_regions']))])
    pair_rows=[]
    for pair in r['family_pairs']:
        if pair['left']<=4 and pair['right']<=4:pair_rows.append([f"{pair['left']}–{pair['right']}",f"{pair['geometry']:.6f}",f"{pair['harmonics']:.6f}",f"{pair['best_cyclic_similarity']:.6f}",f"{pair['best_shift_positions']}/64 cycle"])
    group_rows=[]
    for name,label in [('recovered_522','Recovered'),('remaining_194','Still omitted')]:
        group=r['ambiguous_comparison'][name];group_rows.append([label,str(group['count']),f"{group['shape_best_score']['median']:.6f}",f"{100*group['period_error']['median']:.3f}%",f"{group['periodicity']['median']:.4f}",f"{group['absolute_rms']['median']:.6f}"])
    reason_rows=[[html.escape(' + '.join(v['reasons'])),str(v['count'])] for v in sorted(r['remaining_reason_combinations'],key=lambda v:-v['count'])]
    region_rows=[]
    for v in r['regions']:
        d=v['metrics']['4D'];b=v['metrics']['4F-B'];region_rows.append([str(v['region']),f"{v['start_seconds']:.3f}–{v['end_seconds']:.3f}",f"{v['f0_audio_hz']:.1f}",f"{d['error_ratio']*100:.2f}%",f"{b['error_ratio']*100:.2f}%",f"{b['coverage']*100:.1f}%"])
    onset_rows=[]
    for v in r['audio_energy_onsets']:
        w=v['windows'][0];onset_rows.append([f"{v['onset_seconds']:.6f}",'Yes' if v['recording_start_censored'] else 'No',f"{100*w['error_ratio']:.1f}%",f"{100*w['omitted_fraction_of_error']:.1f}%",f"{100*w['coverage']:.1f}%"])
    gap_table='<div class="table-wrap"><table><thead><tr><th>ID</th><th>Original seconds</th><th>Duration</th><th>Dominant frozen cause</th><th>Cycle IDs</th></tr></thead><tbody>'
    for gap in gaps:
        gap_table+=f'<tr id="gap-{gap["interruption"]}"><td>{gap["interruption"]}</td><td>{gap["start_seconds"]:.6f}–{gap["end_seconds"]:.6f}</td><td>{gap["duration_ms"]:.3f} ms</td><td>{html.escape(gap["dominant_cause"])}</td><td>{html.escape(str(gap["cycle_ids"]))}</td></tr>'
    gap_table+='</tbody></table></div>'
    body=f'''<header><p>Independent waveform-shape research · Experiment 4G</p><h1>Gaps and shape-family fragmentation</h1><p class="lead">The residual contains two different things: omitted original periods, and sharp-edge detail that a rendered cycle failed to reproduce. Four recurring geometric labels are not four discovered sound identities.</p><p><strong>Diagnostic only.</strong> Frozen 1C–4F algorithms and audio are unchanged. No MIDI, isolated stems, combined A+B output, or 4H work.</p><p>Main analysis: <strong>{r['timings']['total_before_report_seconds']:.2f} s</strong> · Peak process memory: <strong>{r['peak_process_rss_bytes']/2**20:.2f} MiB</strong> · Nine calculation/artifact tests passed.</p></header>
<nav aria-label="Report sections"><a href="#causes">Dominant causes</a> · <a href="#interruptions">Locations</a> · <a href="#spikes">Attacks and spikes</a> · <a href="#regions">Region comparison</a> · <a href="#families">Families</a> · <a href="#remaining">194 cycles</a> · <a href="#next">Next changes</a></nav>
<section id="causes"><h2>Dominant measured causes</h2><ol><li><strong>Omissions still dominate B’s residual:</strong> {100*bparts['omitted_original']/btotal:.2f}% of residual energy lies outside modeled support. The 194 remaining ambiguous cycles alone account for {100*remaining_energy/btotal:.2f}% of residual energy. Accepted model error accounts for {100*bparts['accepted_model_error']/btotal:.2f}%.</li><li><strong>Narrow internal-edge spikes are not missing periods:</strong> all 1,546 detected narrow events wholly within rendered B cycles lie near the original’s sharpest within-cycle edge; none is in the bridge zone. Median width is one sample (22.7 microseconds); median phase is 0.5123 cycle. See <a href="#W5">W5</a>.</li><li><strong>A strict, phase-sensitive local gate blocks otherwise strong candidates:</strong> 70 of 194 are rejected only for an unreliable immediate neighbor. Of their 70 bad-neighbor entries, 68 span fewer than four samples; median duration is {statistics.median(v['duration_frames'] for v in bad):.2f} frames. These tiny crossing intervals can make a cycle-index adjacency rule brittle.</li><li><strong>Family labels split articulation/phase variants:</strong> family 2 originated in release, family 3 is release-only in its three historical occurrences, and family 4 is transition-associated. A diagnostic 1/64-cycle rotation increases family 1/4 similarity from 0.932 to 0.995. That supports phase/anchor sensitivity, not automatic identity merging.</li></ol>
{table(['Cause category','Cycles','Share of B residual energy','Evidence'],summary)}<p>The table omits small first/last boundary fragments not owned by a candidate cycle; see exact decomposition in report.json. Percentages describe squared-sample energy, not perceptual importance.</p></section>
<section id="interruptions"><h2>Locate interruptions and classify the evidence</h2><p>Using 2 ms original-audio RMS blocks above 4% of the recording’s maximum block RMS, there are <strong>272 active missing-support intervals</strong> in B: 161 dominated by ambiguous assignment, 109 by unreliable detection candidates, and 2 with no complete candidate (recording/context boundary). Median interval length is {statistics.median(v['duration_ms'] for v in gaps):.3f} ms. Cycle-detection uncertainty is not proof of a missing instrument or a new note.</p><p>All saved outputs are exactly zero outside their accepted cycle supports. <strong>No out-of-support placement was found.</strong> No energetic accepted B cycle exceeded the diagnostic 25%-error-energy threshold, so there is no evidence here for gross whole-cycle placement, gain, or phase failures as the main gap mechanism. Small phase/amplitude/detail errors remain, especially at sharp edges. Shift/gain probes were evaluation only.</p>{table(['Plot','Diagnostic location','Original seconds','Cycle'],case_rows)}{''.join(figures)}<details><summary>All 272 labeled interruption locations</summary>{gap_table}</details><p><a href="interruptions.csv">Download interruption locations (CSV)</a> · <a href="report.json">All evidence and per-cycle probes (JSON)</a></p></section>
<section id="spikes"><h2>Attacks, recognizable bursts, and repeated narrow spikes</h2><p><strong>Short attack bursts are mostly omitted original audio.</strong> Nine energy onsets were independently detected after at least 20 ms of quiet, including a recording-start-censored onset. In the first 5 ms, 19.5–98.8% of source energy remains as error; 92.6–100% of that error lies in omitted support. Original partial cycles before a reliable crossing, transient periodicity uncertainty and immediate-neighbor rejection explain these bursts. They are not all synthesis spikes.</p>{table(['Energy onset (s)','Start censored','First-5-ms error/input','Omitted share of that error','First-5-ms coverage'],onset_rows)}<p><strong>Regular spikes inside rendered cycles have a different mechanism.</strong> Threshold: absolute residual ≥{r['policy']['residual_event_absolute_threshold']:.5f}, fixed at 20% of original full-recording peak for every variant. A “narrow” event spans ≤15% of its local observed period; contiguous threshold samples define an event. All reported fully modeled narrow events are within max(2 frames, 5% of a period) of the source’s sharpest within-cycle slope. Median offset is one frame. Their phase concentration is about 0.998, so they repeat near the same internal cycle position, not at cycle boundaries.</p>{table(['Frozen output','Narrow events','Exposure-normalized count','Median cycle phase','Near original sharp edge','In bridge zone'],spike_rows)}<p>Counts alone are not artifact severity: B renders 1,938 rather than 1,416 cycles, so it exposes more cycles to the unchanged 64-point sampler. The 1,546 B spike events contain 36.3% of accepted-cycle error, but only about 4.18% of total B residual energy. A-256 reduces narrow event counts; A-harmonic still has pitch-dependent high-band phase errors documented in 4F. None is a new combined render. Threshold sensitivity, stereo maximum selection and source band limitation affect event counts; these are not audibility labels.</p></section>
<section id="regions"><h2>Why some regions work and others do not</h2><p>Indices are audio-derived periodic plateaus, not supplied MIDI boundaries or scale positions. Supports include uncertain quiet margins/releases, so time coverage in early regions can be below 100% even while their energetic interiors are continuous. Regions 1–4 and 14–15 have low total error; regions 5, 8 and 11 remain especially incomplete in B. These include repeated audio-derived frequencies around 465 Hz and 620 Hz. B greatly improves other middle regions, so “all middle notes fail” would be inaccurate.</p>{table(['Region','Audio seconds','Median f0 (Hz)','4D error/input','B error/input','B time coverage'],region_rows)}<p>Family 1 spans every pitch region; the failure is not a lack of a primary shape candidate. Higher-pitch and particular sampling/phase geometries make competing exemplars and fixed-phase cosine gates more influential. This is an association within one clip, not a universal pitch rule. Attacks/releases and continuous pitch changes add local boundary uncertainty, but omissions also occur in stable interiors of the silence-separated passage. Continuous transitions are neither necessary nor sufficient for the pattern.</p></section>
<p><strong>Historical scan order also matters:</strong> the competing family-2 exemplar was first created at 0.8800 s, near the fourth short region’s release. Before that, the first regions largely had only the primary exemplar to match. Of 716 historical ambiguous cycles, <strong>713 are in regions 5–13</strong>, one is in the first four and two are in the last two. The later low-frequency regions favor the primary exemplar strongly enough to avoid most competition. This is consistent with exemplar-order and descriptor sensitivity, not a source switching identity on and off.</p><section id="families"><h2>What the four recurring shape families actually contain</h2><p>Each has <strong>one observed exemplar</strong>. “Recurring” means at least three unambiguous historical assignments, not three independent physical sources or a stable-core validation. Four additional one-cycle provisional families remain separate and unconfirmed. The known single-synth description is evaluation context only; no such count was used in discovery.</p>{table(['Family','Exemplars','4C cycles','B rendered cycles','Exemplar seconds','Audio-envelope context','Observed cycle Hz min/median/max','4C region counts'],fam_rows)}<p>Crossing frequency is an audio measurement, with edge-related outliers; it is not a MIDI pitch label. Family 2’s historical 12 occurrences include one release, one silence-backed attack, nine sustain-like cycles and one continuous transition. Family 3’s three occurrences are all low-level release variants. Family 4’s three are all continuous-transition associated. Thus there is <strong>no one-family-per-pitch mapping</strong>.</p>{family_svg}{table(['Families','Signed geometry','Harmonic magnitudes','Best diagnostic cyclic cosine','Diagnostic shift'],pair_rows)}<p>Family 2’s release exemplar is only 0.984827 similar to family 1: just below the 0.985 match gate. Its harmonic magnitudes are 0.999080 similar. Family 3 has much lower amplitude than stable cycles, yet its 46 ms frame can remain periodic because that frame also includes earlier strong audio. Window-level eligibility does not certify each low-level cycle’s boundary/shape reliability. Family 4’s direct cosine is 0.931729; a one-position comparison shift raises it to 0.995001. This indicates an important phase/anchor component, but does not prove the physical boundary is wrong.</p><p><strong>Confirmed:</strong> signed cycle geometry varies measurably with articulation and phase anchoring; first-exemplar matching turns some variants into separate labels. Historical threshold sensitivity yields 2 recurring families at 0.970 versus 4 at 0.985, demonstrating grouping sensitivity. <strong>Not established:</strong> that all four are identical shapes, that every difference is a boundary error, or that merging them would be safe for different-origin audio. Harmonic magnitude similarity loses phase. Release deformation and source/filter/sample-phase variation remain plausible contributors.</p></section>
<section id="remaining"><h2>The remaining 194 versus recovered 522</h2>{table(['Group','Cycles','Median best shape score','Median period error','Median periodicity','Median absolute RMS'],group_rows)}<p>RMS is virtually equal across groups, so simple volume inequality does not explain the omissions. Remaining cycles carry 245.00 squared-sample energy units; recovered cycles carried 699.92. There are 162 sustain-like remaining cycles in the initial conservative envelope labels, so the remainder is not confined to attacks/releases.</p>{table(['Exact rejection-reason combination (disjoint groups)','Cycles'],reason_rows)}<p>The largest exclusive reasons are <strong>70 neighbor-only</strong> and <strong>55 target-score-only</strong>. Individual reason counts overlap, so “114 unreliable-neighbor” and “94 low-score” must not be added. These omissions produce actual intervals in W3/W4 and the CSV, but their audibility is not directly measured; the user’s listening supplies that observation.</p><p>For the 70 neighbor-only cases, the median invalid-neighbor interval is 1.14 samples. Inspecting nearest reliable temporal neighbors, while keeping the old geometry and period criteria, finds only <strong>{context['nearest_reliable_direct_compatible_count']}</strong> with both gaps ≤0.1 cycle. A bounded diagnostic shift of ±0.5/64 cycle raises this comparison count to <strong>{context['nearest_reliable_phase_probe_compatible_count']}</strong>. These are retrospective compatibility probes, <strong>not newly reconstructed or proven-correct cycles</strong>. Fractional shifting linearly smooths the signature slightly, so score improvement does not uniquely identify physical phase error.</p></section>
<section id="next"><h2>Smallest evidence-supported next experiment — not implemented</h2><ol><li><strong>Target the neighbor evidence test first:</strong> inspect nearest reliable neighbors in a tightly bounded time/period neighborhood, and compare neighbor geometry with a bounded phase-tolerance probe, rather than requiring immediately adjacent candidate indices at a fixed phase. Keep the target’s own confidence gates, family relationship policy, original timing/phase, and uncertain intervals intact. Do not render skipped candidate intervals or merge family identities. This addresses the measured micro-crossing/phase sensitivity; the 64/70 comparison is an upper diagnostic opportunity, not a promised gain.</li><li><strong>Leave genuinely weak target matches unresolved initially.</strong> The 55 score-only failures need separate phase/shape/error calibration, not a blind relaxation of 0.995. Negative controls must include genuinely different shapes, polarity, pitch changes, unfamiliar low-level periodic sounds, and real transients.</li><li><strong>Separate core exemplars from articulation/edge variants in a later grouping study.</strong> Require stable evidence before a release/transition exemplar becomes an equally authoritative global competitor. Preserve variants and unfamiliar shapes rather than force one family. This is separate from local continuity and not a reason to combine A+B.</li><li><strong>Treat edge-detail fidelity separately.</strong> The narrow internal spikes require improved phase-consistent rich synthesis; bridge/gap fixes will not restore omitted upper detail. 4F already shows that matching high-frequency energy can worsen its phase-sensitive error. No interpolation, resolution or bridge change was made here.</li></ol><p>Cost estimate, not a benchmark: a bounded lookup over a few nearby cycles is O(cycles), and five 64-position neighbor comparisons add only a few times the compact comparison work (4F-B preparation was 0.027 s). A conservative future implementation should stay far below exhaustive waveform fitting on this clip, but requires fresh timing/memory and false-match tests. No performance or continuity guarantee follows from this diagnostic.</p></section>
<section id="verification"><h2>Scope, runtime and verification</h2><p>Main analysis took {r['timings']['total_before_report_seconds']:.3f} seconds before JSON serialization; peak whole-process RSS was {r['peak_process_rss_bytes']/2**20:.2f} MiB. It includes verification, loading original plus five frozen render/residual pairs, local alignment/gain probes, event/region/family calculations, and final preservation checks. It excludes context probes, HTML/figure building and tests. This is a six-second diagnostic, not a full-song separation benchmark.</p><p>Nine calculation/artifact tests passed: interval locations, fractional cycle masks, residual-energy accounting, stereo polarity, gain/lag classification, audio-phase frame units, bounded phase improvement, different-shape negatives, and independent frozen-WAV location/energy checks. No audio was generated, recognition/grouping/synthesis policy changed, or family reassigned. All earlier files were preserved.</p><p><strong>Historical verification limitation:</strong> 4F’s verification manifest contains a self-entry that hashed its own then-empty file. That self-hash is invalid. Every other recorded 4F source/audio/artifact hash matched. The old manifest remains unchanged; 4G records this limitation and takes an independent before/after preservation snapshot.</p><p>SVG XML, finite coordinates and HTML structure are checked. Browser-rendered preview and independent listening were not performed. Diagnostic energy/event thresholds are not perceptual classifiers. No MIDI, isolated reference stems, or known musical scale entered the calculations. No combined A+B or 4H was started.</p><p><a href="report.json">Full measurements</a> · <a href="context-and-phase-probes.json">Context and bounded-phase evidence</a> · <a href="interruptions.csv">All interruption locations</a> · <a href="preservation.json">Preservation snapshot</a></p></section>'''
    css='''body{font:17px/1.55 system-ui,sans-serif;max-width:1140px;margin:32px auto;padding:0 20px;color:#182735;background:#fff}h1{font-size:2.25rem;line-height:1.15}h2{font-size:1.5rem;margin-top:2rem}nav{position:relative;padding:14px 0;border-block:1px solid #bdc8d3}a{color:#125da8}section{margin-top:35px}.lead{font-size:1.2rem;max-width:85ch}table{border-collapse:collapse;width:100%;font-size:.9rem}th,td{padding:9px 10px;text-align:left;border-bottom:1px solid #c8d1db;vertical-align:top}th{background:#eef2f6}.table-wrap{overflow-x:auto;margin:20px 0}figure{margin:30px 0;padding-top:18px;border-top:1px solid #bdc8d3}svg{max-width:100%;height:auto}figcaption{font-size:.94rem}details{margin:20px 0}summary{font-weight:600}li{margin:9px 0}code{font-family:ui-monospace,monospace}tr:target,figure:target{background:#fff5c5}p{max-width:100ch}'''
    page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Experiment 4G — gap and family diagnostics</title><style>'+css+'</style></head><body>'+body+'</body></html>'
    with (HERE/'report.html').open('x') as f:f.write(page)
    with (HERE/'html-build-timing.json').open('x') as f:json.dump({'html_and_svg_build_seconds':time.perf_counter()-start,'scope':'Separate process, excluding main diagnostic and context probe computation.'},f,indent=2);f.write('\n')
    print('HTML written:',HERE/'report.html')

if __name__=='__main__':run()
